INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('27312173-bdcd-4e87-ab0c-6a2e38e6aa4f', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$21. óra: Gyakorlóóra: a tanult oszthatósági szabályok alkalmazása$q$, $q$Gyakorlás, igaz-hamis állítások, halmazábrák oszthatóságra.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Egész számok, oszthatóság$q$, $q$[{"id": "8fdc4945-f637-481e-9647-a36c512e6d99", "text": "Melyik szám osztható 2-vel, 3-mal és 5-tel is (azaz 30-cal)?", "type": "multiple-choice", "options": [{"id": "9a718355-1ab2-4dc8-bbe5-197beec2a3fb", "text": "90", "isCorrect": true}, {"id": "1662b3c0-bb91-4c54-a6bb-dc6f2cd8145f", "text": "45", "isCorrect": false}, {"id": "b291c108-69b0-4265-970c-d72a1a81f282", "text": "80", "isCorrect": false}, {"id": "6efc7932-8dd6-4214-854f-ad881fb988ea", "text": "100", "isCorrect": false}], "timeLimit": 15}, {"id": "7c70b4ce-408c-4826-9ee0-372e9ff57c43", "text": "A 180 osztható 4-gyel és 9-cel is.", "type": "true-false", "options": [{"id": "9eacd004-4a09-4943-9987-30644ee45866", "text": "Igaz", "isCorrect": true}, {"id": "7056cd1a-1120-45a1-a907-74a42fededfe", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "96534970-7fa8-4fcb-99d8-da7f2fe720e1", "text": "Hány olyan szám van 1 és 100 között, ami osztható 10-zel?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "8522eaa6-80e1-45f9-bfcd-d92e423f6835", "text": "Melyik szám osztható 9-cel?", "type": "multiple-choice", "options": [{"id": "60fa2dda-bc74-493f-9a3a-9e3c70f9d4c8", "text": "729 (7+2+9=18)", "isCorrect": true}, {"id": "62d6dd73-7b5d-4121-879e-7ad8d559b8c1", "text": "721", "isCorrect": false}, {"id": "558a246c-2685-49e4-9e8b-3aadf5dbe998", "text": "725", "isCorrect": false}, {"id": "3e5d5792-7f7a-4ea8-991b-ce5038474841", "text": "730", "isCorrect": false}], "timeLimit": 15}, {"id": "b92fabfc-e4ab-4774-98a7-9bc04bc4ad79", "text": "Ha egy szám osztható 10-zel, akkor 5-tel is osztható.", "type": "true-false", "options": [{"id": "d8a71d53-9ea6-4da3-82b8-7bc152d9bf1f", "text": "Igaz", "isCorrect": true}, {"id": "9b1e3298-bf1f-405c-8246-76f5f3d6644b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "41eb439b-2b99-4885-b605-9e8deb473ec2", "text": "Melyik a legkisebb háromjegyű szám, ami osztható 5-tel?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "7cf27087-a444-4222-86c9-0ab0d244e966", "text": "Melyik a legkisebb háromjegyű szám, ami osztható 3-mal?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "102"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('76e76a06-4b77-40bd-8915-7472704811f3', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$22. óra: Többszörös, közös többszörös$q$, $q$Közös többszörösök, legkisebb közös többszörös (lkkt) és közös nevező.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Egész számok, oszthatóság$q$, $q$[{"id": "fb227d83-e96b-4423-8435-8973a915c203", "text": "Mit jelent két szám legkisebb közös többszöröse (lkkt)?", "type": "multiple-choice", "options": [{"id": "740bfc19-43cd-4797-9cf9-c26d85d633c7", "text": "A legkisebb olyan pozitív számot, amely mindkét számmal osztható", "isCorrect": true}, {"id": "a6392f81-f4bb-4154-921f-015cedb7b18e", "text": "A két szám szorzatát mindig", "isCorrect": false}, {"id": "cb67ab5d-bba4-4741-a0bc-e7fde9b3dc17", "text": "A legkisebb osztót", "isCorrect": false}, {"id": "02b238a4-3324-4d21-b766-33b22ff69743", "text": "A két szám különbségét", "isCorrect": false}], "timeLimit": 15}, {"id": "99fb26b4-9604-4f36-ad54-6ef94b6d3895", "text": "Mennyi a 4 és 6 legkisebb közös többszöröse, lkkt(4, 6)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "5acaf5cf-febe-40a9-8dcb-b2c2d16fb1e5", "text": "Mennyi a 3 és 5 legkisebb közös többszöröse, lkkt(3, 5)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "15"}, {"id": "87dce619-5bc0-4530-8741-bea04d510901", "text": "Relatív prímek (pl. 3 és 5) legkisebb közös többszöröse a két szám szorzata.", "type": "true-false", "options": [{"id": "8dffde72-db3e-4b54-b04b-88000370dba1", "text": "Igaz", "isCorrect": true}, {"id": "3b53249b-074f-4bd1-a5de-0621945f3f83", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "28d5c9ad-a5cb-4463-ad60-688224695075", "text": "A közös többszöröst használjuk törtek közös nevezőre hozásakor.", "type": "true-false", "options": [{"id": "cb22006e-f036-451b-a808-a3808c688d73", "text": "Igaz", "isCorrect": true}, {"id": "dfc4107e-99ca-4501-812f-041c77d96328", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "9bd10fdb-c93b-4e3c-856e-3d01c276c24c", "text": "Mennyi a 6 és 8 legkisebb közös többszöröse?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "24"}, {"id": "529ac43f-884d-4308-b053-6ddb86b38a1e", "text": "Melyik szám közös többszöröse a 2-nek és a 5-nek?", "type": "multiple-choice", "options": [{"id": "2ef737a3-73fd-4bfd-a482-36b5d57697d7", "text": "10", "isCorrect": true}, {"id": "acca0f57-0489-4087-8d1b-b39b8f171c87", "text": "15", "isCorrect": false}, {"id": "475d7ef5-8aad-4581-a721-921cb4918a50", "text": "8", "isCorrect": false}, {"id": "4404f5d1-ff89-4d2b-89ad-60a10a8a56d5", "text": "12", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('9d6198c9-a07a-4ffe-8e79-b018e9beba02', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$23. óra: Osztó, közös osztó$q$, $q$Közös osztók, legnagyobb közös osztó (lnko) és törtek egyszerűsítése.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Egész számok, oszthatóság$q$, $q$[{"id": "90b0c27d-34ba-4d08-9968-69ca0d3b1e83", "text": "Mit jelent két szám legnagyobb közös osztója (lnko)?", "type": "multiple-choice", "options": [{"id": "317844cf-ae47-4602-95f1-be7535a68b72", "text": "A legnagyobb olyan pozitív számot, amely mindkét számot osztja", "isCorrect": true}, {"id": "0fdd4b41-1ae9-438a-8b90-3d36fb4a8cd2", "text": "A két szám összege", "isCorrect": false}, {"id": "e0128c65-2fb0-40db-a160-6e825df878d4", "text": "A legkisebb többszöröst", "isCorrect": false}, {"id": "c5cc2298-e0d9-4d4a-8646-a26274a3aa44", "text": "Az 1-et mindig", "isCorrect": false}], "timeLimit": 15}, {"id": "a4482aa3-7e14-49e4-8bdf-856c0ffff87d", "text": "Mennyi a 12 és 18 legnagyobb közös osztója, lnko(12, 18)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "b13c0258-1933-4e44-b124-94c641ec22a6", "text": "Mennyi a 15 és 25 legnagyobb közös osztója?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "7539490f-ffd4-4c14-89de-144b586c951d", "text": "Két számot relatív prímeknek nevezünk, ha a legnagyobb közös osztójuk 1.", "type": "true-false", "options": [{"id": "1de7cf3d-b5ca-4ec4-a9b3-f4d9790fc83b", "text": "Igaz", "isCorrect": true}, {"id": "7a7bb9d5-d8a8-4381-bca4-da7f5c88f619", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "55a44baa-5fa7-43e3-8f2a-064e639e07e8", "text": "A 8 és 9 relatív prímek (lnko(8,9) = 1).", "type": "true-false", "options": [{"id": "30197081-8caf-4a62-9377-3d833ba42e0e", "text": "Igaz", "isCorrect": true}, {"id": "920adf42-a5f7-4362-aa62-c9f9d87f01d4", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "4559886a-cd81-47ae-962f-d846b46a0d99", "text": "A legnagyobb közös osztóval egyszerűsítve a törtet a legegyszerűbb alakot kapjuk.", "type": "true-false", "options": [{"id": "b1b3e9d4-bd5c-43f9-ada8-acb1b31853a0", "text": "Igaz", "isCorrect": true}, {"id": "7dca4275-bcf3-4ea7-bce5-5d18d274eb14", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "54c1396b-5848-46ae-b1d9-87fb90fc6d99", "text": "Mennyi a 20 és 30 legnagyobb közös osztója?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('cb22ca08-67fc-497c-ae0a-574254771b4b', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$24. óra: Összefoglalás$q$, $q$A tanult fogalmak ismétlése, rendszerezése az egész számok és oszthatóság témakörből.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Egész számok, oszthatóság$q$, $q$[{"id": "86b36058-201e-47cd-8c4e-5e1e6877c8f9", "text": "Mennyi (-12) * (-5)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}, {"id": "71c7821d-d240-4ca6-a7e3-979e04e292fd", "text": "Mennyi lkkt(6, 9)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "18"}, {"id": "f40b28b9-4fca-4e61-9b67-50251221463b", "text": "Mennyi lnko(24, 36)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "e9b9f9ec-ce81-4122-bccd-6cc7061cc773", "text": "A 135 osztható 5-tel és 9-cel is.", "type": "true-false", "options": [{"id": "1c2f52d0-238a-4f79-9162-1274ad9af5da", "text": "Igaz", "isCorrect": true}, {"id": "9c36b233-0b9f-4f6d-84f6-0dcacab9bcf4", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "fbe652e1-b918-4040-98fe-a66312a2a775", "text": "A 2 az egyetlen páros prímszám.", "type": "true-false", "options": [{"id": "1ddc1e8a-3ec0-4345-957a-a7948a217cd3", "text": "Igaz", "isCorrect": true}, {"id": "a56127e5-60a3-48bc-8b1b-7e929b7ef645", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "83493e25-002d-4511-97e8-97e40bbcc262", "text": "Mennyi (-50) : (+10)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-5"}, {"id": "0645159b-680d-4616-8d73-b0575d575881", "text": "Melyik szám osztható 4-gyel?", "type": "multiple-choice", "options": [{"id": "4fac052b-6ae5-4eaa-b8b1-f2b6a3cceda9", "text": "524", "isCorrect": true}, {"id": "4bff086d-7c9b-4d34-aede-71eeb6bdc906", "text": "522", "isCorrect": false}, {"id": "ece5b8e8-7af8-4ffe-a07f-d53d5dabf239", "text": "521", "isCorrect": false}, {"id": "958fbc92-823b-4e8b-9fc4-f851c5a7d143", "text": "523", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('b7023fb9-7ff0-4d6f-981a-eeb66dae3c65', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$25. óra: Tesztfeladatok megoldása$q$, $q$Feladatmegoldási gyakorlat önállóan az oszthatósági téma lezárása előtt.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Egész számok, oszthatóság$q$, $q$[{"id": "f70180c7-0ec3-453a-b191-8aeb7b9e19d9", "text": "Hány osztója van a 10-nek? (1, 2, 5, 10)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "90ac3cd8-beb9-4dc6-a4e5-c860615a5b5f", "text": "Osztható-e a 432 6-tal?", "type": "true-false", "options": [{"id": "5ace7dea-6479-4ba0-a085-c2bdb5fefa17", "text": "Igaz (páros és 4+3+2=9)", "isCorrect": true}, {"id": "590eff86-2482-4206-a7d8-1622e80a7640", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "58512edc-6e1c-4e22-ac40-8d05d36c3f49", "text": "Mennyi (-7) * (+6)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-42"}, {"id": "d788c3f8-4ffd-4ef1-ab6f-e61487d014c2", "text": "Melyik szorzat eredménye pozitív?", "type": "multiple-choice", "options": [{"id": "d8b17de6-f1cd-4d19-9a74-19262b8b0c93", "text": "(-4) * (-5)", "isCorrect": true}, {"id": "aadd1ceb-c2e6-4301-9e9f-274df8933033", "text": "(-4) * (+5)", "isCorrect": false}, {"id": "c672eac4-9491-49f9-adbe-246fac6a39bb", "text": "(+4) * (-5)", "isCorrect": false}, {"id": "00379b07-68c1-4bc7-8dbf-43ed2109bfdc", "text": "(-4) * 0", "isCorrect": false}], "timeLimit": 15}, {"id": "3e669fc5-ed0a-4ee9-b256-d172313cee19", "text": "Mennyi a maradék, ha 47-et 5-tel osztunk?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "8f5a74be-24de-4e05-87d7-a97ef698b5c6", "text": "A 17 prímszám.", "type": "true-false", "options": [{"id": "03cd69fc-7187-44cd-912e-343ef313a153", "text": "Igaz", "isCorrect": true}, {"id": "e75d67ba-7c5d-42b2-8e23-fdb164b43450", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "6a4979f2-3c12-41a1-be60-2ca03f612661", "text": "Mennyi lkkt(4, 10)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('266a956a-418c-41ed-bbb1-2c56d31514a6', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$26. óra: Témazáró dolgozat$q$, $q$Témazáró számonkérés az Egész számok és oszthatóság témakörből (10 kérdés).$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Egész számok, oszthatóság$q$, $q$[{"id": "99eef2f6-f70f-4e35-aa30-a1ba49f5ff47", "text": "1. Mennyi (-18) + (+30)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "5dabd219-509c-47cb-abcf-a7cb7986dd98", "text": "2. Mennyi (-7) * (-9)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "63"}, {"id": "c72a3d14-c4c2-45d0-852a-671b8c669dfb", "text": "3. Mennyi (-72) : (+8)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-9"}, {"id": "df381d4f-9132-4222-809e-55ba94eb567d", "text": "4. Osztható-e a 534 3-mal?", "type": "true-false", "options": [{"id": "c9dc2d45-54a8-4110-a791-47aa58122213", "text": "Igaz (5+3+4=12)", "isCorrect": true}, {"id": "de52ab86-a3a1-4fa7-95aa-b37c5412236f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "e342d9a9-1db4-48a1-b3fd-cb867f49495b", "text": "5. Osztható-e a 620 4-gyel?", "type": "true-false", "options": [{"id": "6a00f535-9ae1-4f47-959f-f4d6b5856ea1", "text": "Igaz (20 osztható 4-gyel)", "isCorrect": true}, {"id": "425306d9-7565-47df-9a0c-09aee8806e27", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "6ebd850a-2135-4847-b478-afc12440f831", "text": "6. Mennyi lkkt(6, 10)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "facc5cf5-1b00-4125-9914-17c676fd9bd3", "text": "7. Mennyi lnko(18, 24)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "4cc1d503-8ede-4294-a0c5-25138a487cc6", "text": "8. Hány prímszám van 1 és 10 között? (2, 3, 5, 7)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "10b189f0-5d3d-40dd-aca6-68d69b9e3e92", "text": "9. Hányféleképpen ülhet le 3 gyermek 3 székre?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "f8025b3d-7a05-4b2c-a3bb-58c9a1ddaf9b", "text": "10. Két negatív szám szorzata mindig pozitív.", "type": "true-false", "options": [{"id": "42ce9326-238b-43e7-bdb2-90045ad2ad5b", "text": "Igaz", "isCorrect": true}, {"id": "48deb364-cae2-4b25-b033-a2291d22e5e7", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('b25442bd-5bd9-47db-9985-6e0ae54032e8', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$27. óra: Témazáró dolgozat értékelése$q$, $q$A témazáró dolgozat megbeszélése, hibák elemzése, tapasztalatok összegzése.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Egész számok, oszthatóság$q$, $q$[{"id": "a69a6626-e35f-41b0-b1dd-cd6c3f801476", "text": "Mi volt a leggyakoribb hiba az előjelszabályok alkalmazásakor?", "type": "multiple-choice", "options": [{"id": "a482f1e5-1a9f-4619-a230-58f318f9520e", "text": "A szorzás/osztás és összeadás előjelszabályainak összetévesztése", "isCorrect": true}, {"id": "e87ded2a-a311-4532-ac43-268d65926a62", "text": "A számok leírása", "isCorrect": false}, {"id": "e536dfa1-a4ab-4eb5-a513-db08952caba6", "text": "A vonalzó használata", "isCorrect": false}, {"id": "32a96f96-ae0e-4557-a50b-b7adb63261ef", "text": "A válasz elhagyása", "isCorrect": false}], "timeLimit": 15}, {"id": "df89a5cd-d2fe-404c-959e-44a83d27f811", "text": "Az osztási szabályok (pl. 3-mal, 9-cel) esetén a számjegyek összege a döntő.", "type": "true-false", "options": [{"id": "1657537c-73d3-40b0-b0e4-65220ea5b734", "text": "Igaz", "isCorrect": true}, {"id": "b0489e19-d97e-45b0-b991-accfb3eb89f7", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "53e49172-3ea9-4350-84c3-08b524e54638", "text": "Mennyi (-5) * (-5)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "25"}, {"id": "90b3d917-20e9-4f1f-ae3d-46bfd9cdca67", "text": "A lkkt meghatározásánál a többszörösök közül a legkisebbet választjuk.", "type": "true-false", "options": [{"id": "cce38856-30dd-4aca-90c1-f43098275916", "text": "Igaz", "isCorrect": true}, {"id": "3b9fee59-c1c9-4c86-ae9d-61c13de3041d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "fc5edf20-384c-4450-a372-787f4219dde1", "text": "Mennyi (-30) : (-5)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "d2365a65-e31d-424c-b7cb-a7c1724eb00d", "text": "A dolgozatok áttekintése segít a hiányosságok pótlásában.", "type": "true-false", "options": [{"id": "598b3612-da71-4317-b893-2758db067a58", "text": "Igaz", "isCorrect": true}, {"id": "3e927cf3-87e3-4084-8642-6d5c2a115d0e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "fd199f92-d4f8-4191-a3fb-420e0c2240e0", "text": "Mennyi lnko(10, 15)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('084c103f-21e9-46cd-9744-612cdb9e0268', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$28. óra: Mit tanultunk a törtekről? Ismétlés$q$, $q$Ötödikben tanult ismeretek: közönséges tört értelmezése, számláló, nevező, bővítés, egyszerűsítés.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Törtek$q$, $q$[{"id": "9e0d2583-8dfd-44ae-99a1-7233a0c735f0", "text": "Mi a közönséges tört felső száma?", "type": "multiple-choice", "options": [{"id": "ef6b54bf-6db6-4e60-8817-50f9552084d8", "text": "Számláló", "isCorrect": true}, {"id": "eb8faec0-7472-4f4b-b70a-d5f6d4a4558c", "text": "Nevező", "isCorrect": false}, {"id": "f697f304-9904-49af-b2df-e0b8ed2e248f", "text": "Törtvonal", "isCorrect": false}, {"id": "6b497262-aaaf-418d-b6a3-e9220771dbc7", "text": "Egész rész", "isCorrect": false}], "timeLimit": 15}, {"id": "af3c8180-039d-4df3-ba77-3d147174e69b", "text": "Mi a közönséges tört alsó száma?", "type": "multiple-choice", "options": [{"id": "ea1ea6c4-5b34-4696-8f99-1b27c397f737", "text": "Nevező", "isCorrect": true}, {"id": "bd3b32ed-5cb2-4658-9711-aff5add19864", "text": "Számláló", "isCorrect": false}, {"id": "bef4f3a2-e3e6-44e8-a183-e014147a2bdd", "text": "Osztó", "isCorrect": false}, {"id": "ac5ca2fe-027d-4c91-99f2-eceebd875496", "text": "Különbség", "isCorrect": false}], "timeLimit": 15}, {"id": "ebbd8ac3-5303-4e41-b99b-1139940219f2", "text": "Mennyi a 3/4 bővítve 2-vel?", "type": "multiple-choice", "options": [{"id": "0a9c3268-3cd4-4dcc-9c4a-b6d02e646099", "text": "6/8", "isCorrect": true}, {"id": "358c4527-860b-4e32-ad0f-7d6a39a297d6", "text": "5/6", "isCorrect": false}, {"id": "8b24223f-2ff8-4a2a-a185-23d1422af20d", "text": "3/8", "isCorrect": false}, {"id": "ceda918a-ab4e-4dc0-b655-2f19663d6289", "text": "6/4", "isCorrect": false}], "timeLimit": 15}, {"id": "9eb3bc76-01e2-43c7-93e6-52bd06e374a9", "text": "Mennyi a 6/10 egyszerűsítve 2-vel?", "type": "multiple-choice", "options": [{"id": "c807c6b1-c22b-4921-8d0d-5e9b809b2388", "text": "3/5", "isCorrect": true}, {"id": "77609986-0aa5-4ff7-835a-8c7aa7ea0eef", "text": "3/10", "isCorrect": false}, {"id": "058e0dea-4ce4-491e-8e11-53a29ac73da1", "text": "6/5", "isCorrect": false}, {"id": "ac014c44-76ed-4544-aa08-fa7636bca4ea", "text": "1/2", "isCorrect": false}], "timeLimit": 15}, {"id": "4e507635-b945-4b18-a087-418cad9036d7", "text": "A tört értéke nem változik, ha számlálóját és nevezőjét ugyanazzal a nem-nulla számmal szorozzuk (bővítjük).", "type": "true-false", "options": [{"id": "b5404bac-e5c8-4818-a34b-840b008ddab8", "text": "Igaz", "isCorrect": true}, {"id": "79c0d1d5-eed1-4b85-a5d3-049417b86aee", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "33eb6ea1-276a-46f8-b150-d8df9f4d5ebc", "text": "Hány negyedből áll 1 egész?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "a9846cc8-c8e3-4082-9097-dd75602ff2a0", "text": "Mennyi 1/2 + 1/4?", "type": "multiple-choice", "options": [{"id": "e256d8fd-eb96-406e-a283-e85f7abad66f", "text": "3/4 (2/4 + 1/4)", "isCorrect": true}, {"id": "ded93aa6-c4fe-424d-b363-bec9bf13ba74", "text": "2/6", "isCorrect": false}, {"id": "7cbb9420-9125-419f-ac9c-61df9b8ec6a2", "text": "2/4", "isCorrect": false}, {"id": "c6787d36-f47b-4481-9cb8-6120b43e6754", "text": "1/6", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('05687247-4b0e-4939-96af-f857130a4ba0', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$29. óra: Mit tanultunk a törtekről? Ismétlés II.$q$, $q$Összeadás és kivonás azonos és különböző nevezőjű törtekkel.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Törtek$q$, $q$[{"id": "0a7f59be-5169-4e4f-9dd9-25ce8a9e7985", "text": "Hogyan adjuk össze a különböző nevezőjű törteket?", "type": "multiple-choice", "options": [{"id": "43caedb0-b6ed-42bf-b508-b8b926b22ff6", "text": "Közös nevezőre hozzuk őket, majd a számlálókat összeadjuk", "isCorrect": true}, {"id": "90060fbc-1081-4831-b143-78598aaeb3a5", "text": "A számlálókat és nevezőket is összeadjuk", "isCorrect": false}, {"id": "a1597c70-6ac1-473f-bbc2-ee8050812089", "text": "A számlálókat megszorozzuk", "isCorrect": false}, {"id": "c2adfcdc-27c7-4087-a55e-fdd95f21e43a", "text": "Nem lehet összeadni őket", "isCorrect": false}], "timeLimit": 15}, {"id": "02a5003b-2322-499f-b378-62a715727a31", "text": "Mennyi 1/3 + 1/6? (2/6 + 1/6)", "type": "multiple-choice", "options": [{"id": "ee9c12e7-4cbb-432b-98b8-b5f2552a9775", "text": "3/6 (azaz 1/2)", "isCorrect": true}, {"id": "67e02aeb-158a-45e7-a6b2-53d45db02d82", "text": "2/9", "isCorrect": false}, {"id": "9efebd5f-6c41-4131-b11f-c735a1faba02", "text": "1/9", "isCorrect": false}, {"id": "95ffac00-5398-48a1-b84f-e6955e19d385", "text": "2/6", "isCorrect": false}], "timeLimit": 15}, {"id": "26e9efbf-0148-4c6d-a833-8b88a6345473", "text": "Mennyi 5/8 - 3/8?", "type": "multiple-choice", "options": [{"id": "b3faf913-1662-4834-94dc-c69e4e305fdf", "text": "2/8 (azaz 1/4)", "isCorrect": true}, {"id": "6979778c-c20e-43f0-b510-d9b97a6a275e", "text": "2/0", "isCorrect": false}, {"id": "bb879e8f-cce0-416a-bdd2-3f583f14b2f0", "text": "8/8", "isCorrect": false}, {"id": "2dd01033-6251-42bb-955d-7fcc629dd926", "text": "1/8", "isCorrect": false}], "timeLimit": 15}, {"id": "4a889d61-d253-495f-8f18-45d70a2bfd19", "text": "Az 1/2 és 2/4 egyenlő értékű törtek.", "type": "true-false", "options": [{"id": "651eb780-2585-488d-b897-ac0df7b90e66", "text": "Igaz", "isCorrect": true}, {"id": "1cc777f1-89d2-4aed-b635-455e1b399a89", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "6b891e49-28d6-40b0-8ddd-ea43fbfa5da9", "text": "Hány nyolcad van 3/4-ben?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "dcfd7738-8a96-47fd-851d-5a28ed5d5e3d", "text": "Mennyi 1 egészből kivonva 2/5-öt?", "type": "multiple-choice", "options": [{"id": "f9a0a236-1d2a-4060-a1be-79a1051e41c3", "text": "3/5", "isCorrect": true}, {"id": "f15af15e-c933-4223-a7c9-1e043fe40d43", "text": "1/5", "isCorrect": false}, {"id": "95e64ab7-841b-4379-b06f-d3823ad24749", "text": "2/5", "isCorrect": false}, {"id": "590702c7-adae-48c7-9722-1a7f8580994a", "text": "5/5", "isCorrect": false}], "timeLimit": 15}, {"id": "bf4f2220-e576-4405-a5bd-c856560f53c9", "text": "A törtvonal osztás műveletet jelent.", "type": "true-false", "options": [{"id": "11e35a22-d857-4047-be7e-23ce68b23ecf", "text": "Igaz", "isCorrect": true}, {"id": "ca27f530-ce4f-4420-a1ca-e9ebf3b9f3eb", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('17ee2684-44e7-4634-a5a1-db5e5429dbed', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$30. óra: Szorzás törttel, a reciprok$q$, $q$Tört szorzása törttel, reciprok fogalma.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Törtek$q$, $q$[{"id": "b57af948-9372-4d18-93a5-f90aa71a84d2", "text": "Hogyan szorzunk törttel törtet?", "type": "multiple-choice", "options": [{"id": "25baf171-caff-4784-830a-c51c7624d911", "text": "A számlálót a számlálóval, a nevezőt a nevezővel szorozzuk", "isCorrect": true}, {"id": "25a3310a-b341-4a6f-a67e-8ad201cd7ba5", "text": "Közös nevezőre hozzuk őket", "isCorrect": false}, {"id": "309259c3-f910-48b6-8039-d762cd340ee0", "text": "A számlálót a nevezővel szorozzuk", "isCorrect": false}, {"id": "66e99bbc-a3b6-46aa-8179-8a786a7e812d", "text": "Keresztbe szorzunk", "isCorrect": false}], "timeLimit": 15}, {"id": "6c5cfc05-913a-4d3c-b690-a42a89bc1821", "text": "Mennyi 2/3 * 3/5?", "type": "multiple-choice", "options": [{"id": "3702f400-8903-4af9-91a2-3a9feca0e5bb", "text": "6/15 (azaz 2/5)", "isCorrect": true}, {"id": "50d02172-959e-43b8-8416-9b6cb1ae157a", "text": "5/8", "isCorrect": false}, {"id": "5f99da76-6d02-4cc1-8484-8474601bc297", "text": "6/8", "isCorrect": false}, {"id": "ac240e4b-5c02-4522-a11f-b5baf5444323", "text": "2/15", "isCorrect": false}], "timeLimit": 15}, {"id": "a98497a7-9dc4-4dfd-88cd-fc04774767cd", "text": "Mi a 3/4 reciproka?", "type": "multiple-choice", "options": [{"id": "a19b32de-c2ef-4c3e-945b-747539de1109", "text": "4/3", "isCorrect": true}, {"id": "31299966-3679-42d1-90e5-2e90deb390be", "text": "-3/4", "isCorrect": false}, {"id": "579541cc-8d26-4ba8-970a-8e005ee33a81", "text": "1/4", "isCorrect": false}, {"id": "3f44758b-e37c-4c78-bbdb-d4a95cbc9ed4", "text": "3/4", "isCorrect": false}], "timeLimit": 15}, {"id": "0d3b357f-60cc-45e0-95e0-99815a66f481", "text": "Egy szám és a reciproka szorzata mindig 1.", "type": "true-false", "options": [{"id": "8a44370d-51af-47d2-b15f-bd998e79c638", "text": "Igaz", "isCorrect": true}, {"id": "f0c9f3b5-6a3f-4c0e-9bb5-061583c3f6de", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "f88846e3-a5f8-4df2-bd89-6ee2db122f5b", "text": "Mi a 5 egész reciproka?", "type": "multiple-choice", "options": [{"id": "e0a472f2-4488-485c-a0ac-6de930d9a8d9", "text": "1/5", "isCorrect": true}, {"id": "11c59139-c28c-4dda-ad9f-2a05828ff5e4", "text": "-5", "isCorrect": false}, {"id": "2f7c49bc-953b-40b5-ae86-a95d0e05078a", "text": "5/1", "isCorrect": false}, {"id": "a40c7b9a-b9a8-466d-a0cf-636ab737c927", "text": "0", "isCorrect": false}], "timeLimit": 15}, {"id": "bc86e1a8-2258-4174-9f0d-cdc373128c8f", "text": "A 0-nak nincs reciproka.", "type": "true-false", "options": [{"id": "5b86d9b0-8d95-44f2-bae4-fdccdd246367", "text": "Igaz", "isCorrect": true}, {"id": "07faf55d-707b-4d9e-84a7-4dc736970f34", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "1e23040d-e06b-4941-a83f-d1775216983f", "text": "Mennyi 1/2 * 1/3?", "type": "multiple-choice", "options": [{"id": "953d09d4-9a8b-43d3-a6a6-4b5271542384", "text": "1/6", "isCorrect": true}, {"id": "a21b65aa-58ff-457f-bc7c-b17f614837e6", "text": "2/5", "isCorrect": false}, {"id": "35f03774-5fff-4758-b9eb-bbda8ce1b55c", "text": "1/5", "isCorrect": false}, {"id": "1adcf588-20e1-4a21-ae4a-c40e8ef41d22", "text": "2/6", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;